var a=[{title:`Respirația la exercițiile cu rezistență`,text:`La o flotare sau o genuflexiune obișnuită, încearcă să inspiri în faza mai ușoară, de coborâre, și să expiri în timpul efortului. Țintește un tipar pe care îl poți repeta fără să gâfâi sau să pierzi controlul. Există excepții: ridicările solicitante pot folosi o scurtă oprire deliberată a respirației pentru a rigidiza trunchiul, sub supraveghere calificată.`},{title:`Încordarea trunchiului și oprirea respirației`,text:`Tensiunea abdominală coordonată poate ajuta la stabilizarea coloanei. Manevra Valsalva (o expirație forțată împotriva căilor respiratorii închise) poate provoca schimbări mari, pe termen scurt, ale tensiunii arteriale și ale circulației. Nu este pentru oricine, mai ales pentru persoanele cu hipertensiune, boli cardiovasculare sau alte probleme medicale relevante.`},{title:`Respirația în timpul cardio`,text:`Pe măsură ce intensitatea crește, respiri mai mult ca să aduci oxigen și să elimini dioxidul de carbon. Nu trebuie să potrivești fiecare pas cu un număr exact de inspirații și expirații. Un tipar natural, confortabil, este bun pentru majoritatea activităților ușoare, iar la intervalele grele poți lăsa respirația să se accelereze cât are nevoie.`},{title:`Exemplu`,text:`La o serie de zece genuflexiuni goblet, inspiră înainte să cobori, rămâi ușor încordat și expiră când te ridici. Dacă te amețești, oprește-te și odihnește-te. Nu te forța. La o plimbare sau o tură ușoară, faptul că poți vorbi este o bună verificare că efortul rămâne moderat.`},{title:`Greșeli frecvente`,text:`Să îți ții respirația pe parcursul mai multor repetări, să forțezi un tipar foarte lent în timpul unui cardio intens și să confunzi respirația zgomotoasă cu un antrenament bun îți încurcă controlul intensității.`},{title:`Când te faci verificat`,text:`Dacă rămâi des fără suflu fără o cauză clară, te simți pe punctul de a leșina sau ai simptome în piept, mergi la medic. O altă tehnică de respirație nu le va rezolva.`}];var r=[{label:`CDC: intensitatea și respirația`,url:`https://www.cdc.gov/physical-activity-basics/measuring/`},{label:`Ghidul American Heart Association privind exercițiile`,url:`https://www.heart.org/en/healthy-living/exercise-and-physical-activity/`}];var t={sections:a,sources:r};export{t as default,a as sections,r as sources};